arguments.content:
body {
  font-family: sans-serif;
  background-color: #f4f4f9;
  margin: 0;
  padding: 20px;
}

h1 {
  text-align: center;
}

.board {
  display: flex;
  gap: 20px;
  justify-content: center;
  align-items: flex-start;
}

.column {
  background-color: #ebedf0;
  border-radius: 8px;
  width: 300px;
  min-height: 400px;
