  // Optimistic update: add a placeholder card
  const tempId = `temp-${Date.now()}`;
  const newCard = { id: tempId, column_id: columnId, text, position: 0 };

  const col = boardState.find(c => c.id === columnId);
  if (col) {
    col.cards.push(newCard);
    renderBoard();
  }

