{"content": "const express = require('express');
const cors = require('cors');
const { PGLite } = require('@electric-sql/pglite');
const path = require('path');
const fs = require('fs');

const app = express();
app.use(cors());
app.use(express.json());

const DB_DIR = path.join(__dirname, 'data');
if (!fs.existsSync(DB_DIR)) {
  fs.mkdirSync(DB_DIR);
}

const db = new PGLite(DB_DIR);

// SSE management
let clients = [];

const broadcast = (type, data) => {
  clients.forEach(client => {
    client.res.write(`data: ${JSON.stringify({ type, data })}\n\n`);
  });
};

async function initDb() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS columns (
      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      position DOUBLE PRECISION NOT NULL
    );

    CREATE TABLE IF NOT EXISTS cards (
      id TEXT PRIMARY KEY,
      column_id TEXT REFERENCES columns(id) ON DELETE CASCADE,
      text TEXT NOT NULL,
      position DOUBLE PRECISION NOT NULL,
      created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    );
  `);

  const colCount = await db.query('SELECT COUNT(*) FROM columns');
  if (parseInt(colCount.rows[0].count) === 0) {
    await db.query(`
      INSERT INTO columns (id, title, position) VALUES
      ('col-1', 'To Do', 1.0),
      ('col-2', 'In Progress', 2.0),
      ('col-3', 'Done', 3.0);
    `);
    console.log('Seeded columns');
  }
}

initDb().catch(console.error);

// API Endpoints

app.get('/api/board', async (req, res) => {
  try {
    const columns = await db.query('SELECT * FROM columns ORDER BY position ASC');
    const cards = await db.query('SELECT * FROM cards ORDER BY position ASC');

    const board = columns.rows.map(col => ({
      ...col,
      cards: cards.rows.filter(card => card.column_id === col.id)
    }));

    res.json(board);
  } catch (err) {
    console.error(err);
    res.status(500).send('Error fetching board');
  }
});

app.post('/api/cards', async (req, res) => {
  const { columnId, text } = req.body;
  if (!columnId || !text) return res.status(400).send('Missing columnId or text');

  try {
    // Get the last card's position in this column
    const lastCard = await db.query(
      'SELECT position FROM cards WHERE column_id = $1 ORDER BY position DESC LIMIT 1',
      [columnId]
    );

    let newPosition = 1.0;
    if (lastCard.rows.length > 0) {
      newPosition = lastCard.rows[0].position + 1.0;
    }

    const id = `card-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    await db.query(
      'INSERT INTO cards (id, column_id, text, position) VALUES ($1, $2, $3, $4)',
      [id, columnId, text, newPosition]
    );

    const newCard = { id, column_id: columnId, text, position: newPosition };

    broadcast('CARD_CREATED', newCard);
    res.status(201).json(newCard);
  } catch (err) {
    console.error(err);
    res.status(500).send('Error creating card');
  }
});

app.patch('/api/cards/:id/move', async (req, res) => {
  const { id } = req.params;
  const { columnId, beforeId, afterId } = req.body;

  try {
    await db.transaction(async (tx) => {
      // 1. Get current card info
      const cardResult = await tx.query('SELECT column_id, position FROM cards WHERE id = $1', [id]);
      if (cardResult.rows.length === 0) throw new Error('Card not found');

      // 2. Calculate new position
      let newPosition;
      if (beforeId && afterId) {
        // Between two cards
        const beforeResult = await tx.query('SELECT position FROM cards WHERE id = $1', [beforeId]);
        const afterResult = await tx.query('SELECT position FROM cards WHERE id = $1', [afterId]);

        if (beforeResult.rows.length === 0 || afterResult.rows.length === 0) {
            throw new Error('Invalid beforeId or afterId');
        }

        const posBefore = beforeResult.rows[0].position;
        const posAfter = afterResult.rows[0].position;
        newPosition = (posBefore + posAfter) / 2;
      } else if (beforeId) {
        // After beforeId
        const beforeResult = await tx.query('SELECT position FROM cards WHERE id = $1', [beforeId]);
        if (beforeResult.rows.length === 0) throw new Error('Invalid beforeId');
        newPosition = beforeResult.rows[0].position + 1.0;
      } else if (afterId) {
        // Before afterId
        const afterResult = await tx.query('SELECT position FROM cards WHERE id = $1', [afterId]);
        if (afterResult.rows.length === 0) throw new Error('Invalid afterId');
        newPosition = afterResult.rows[0].position - 1.0;
      } else {
        // Fallback - just use a default or handle error
        throw new Error('Must provide beforeId or afterId');
      }

      // 3. Update card
      await tx.query(
        'UPDATE cards SET column_id = $1, position = $2 WHERE id = $3',
        [columnId, newPosition, id]
      );

      // 4. Check for position collisions or very small gaps (renormalization)
      // For simplicity in this MVP, we just check if the new position is extremely close to others
      // and if so, we could renormalize. But let's see if fractional works for a while.
      // A better way is to periodically renormalize.

      // Let's implement a simple check: if there's a collision, renormalize the column.
      const collisionCheck = await tx.query(
        'SELECT id FROM cards WHERE column_id = $1 AND position = $2',
        [columnId, newPosition]
      );

      if (collisionCheck.rows.length > 1) {
          // Collision detected! Renormalize the column.
          const allCards = await tx.query(
              'SELECT id, text FROM cards WHERE column_id = $1 ORDER BY position ASC',
              [columnId]
          );
          // Note: we should also include the card we are moving in this re-ordering
          // but it's already in the table.

          // We need to re-calculate positions for all cards in the column.
          // We'll do it in a loop to avoid infinite recursion if needed, but here it's fine.
          for (let i = 0; i < allCards.rows.length; i++) {
              await tx.query(
                  'UPDATE cards SET position = $1 WHERE id = $2',
                  [i + 1.0, allCards.rows[i].id]
              );
          }
          // Note: after renormalization, the card's position has changed.
          // We need to return the new position.
          const finalCardResult = await tx.query('SELECT id, column_id, text, position FROM cards WHERE id = $1', [id]);
          const updatedCard = finalCardResult.rows[0];

          // Broadcast the whole column or just the update? 
          // To keep it simple, we broadcast the updated card.
          // But if multiple cards changed position, we might need to broadcast more.
          // For now, let's broadcast the updated card.
          broadcast('CARD_MOVED', updatedCard);
          res.json(updatedCard);
          return;
      }

      const updatedCard = { id, column_id: columnId, text: '', position: newPosition }; // text not returned in query above, let's fix
      // Actually let's get the text
      const cardDetails = await tx.query('SELECT text FROM cards WHERE id = $1', [id]);
      updatedCard.text = cardDetails.rows[0].text;

      broadcast('CARD_MOVED', updatedCard);
      res.json(updatedCard);
    });
  } catch (err) {
    console.error(err);
    res.status(500).send('Error moving card: ' + err.message);
  }
});

app.get('/api/stream', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.setHeader('Connection', 'keep-alive');

  const clientId = Date.now();
  const newClient = { id: clientId, res };
  clients.push(newClient);

  console.log(`Client ${clientId} connected`);

  req.on('close', () => {
    console.log(`Client ${clientId} disconnected`);
    clients = clients.filter(c => c.id !== clientId);
  });
});

const PORT = 3001;
app.listen(PORT, () => {
  console.log(`Backend listening on port ${PORT}`);
});
