      const updatedCard = { id, column_id: columnId, text: '', position: newPosition }; // text not returned in query above, let's fix
      // Actually let's get the text
      const cardDetails = await tx.query('SELECT text FROM cards WHERE id = $1', [id]);
      updatedCard.text = cardDetails.rows[0].text;

      broadcast('CARD_MOVED', updatedCard);
      res.json(updatedCard);
    });
  } catch (err) {
    console.error(err);
    res.status(500).send('Error moving card: ' + err.message);
  }
});

