    const rect = cardUnderMouse.getBoundingClientRect();
    const isAfter = (e.clientY - rect.top) > (rect.height / 2);
    if (isAfter) {
      cardsContainer.appendChild(el);
    } else {
      cardsContainer.insertBefore(el, cardUnderMouse);
    }
