    if (type === 'CARD_CREATED' || type === 'CARD_MOVED') {
      reconcileCard(data);
    }
  };

  eventSource.onerror = (err) => {
    console.error('SSE error:', err);
    eventSource.close();
    // Retry after a delay
    setTimeout(setupSSE, 5000);
  };
}

// Initial load
fetchBoard();
setupSSE();
